// Key improvements for ConceptBoard.js dropdown section

// Replace the dropdown section with this enhanced version:

{/* Enhanced dropdown with multi-selection and better connection management */}
{hoveredImageId === img.id && (
  <div 
    className="absolute bg-black bg-opacity-95 border border-gray-600 rounded-b-lg shadow-xl p-3"
    style={{
      bottom: 0,
      left: 0,
      right: 0,
      zIndex: 1001,
    }}
  >
    <div className="text-white text-center mb-3">
      <div className="font-semibold text-sm text-gray-200 mb-2">{img.name}</div>
      
      {/* Show current connections */}
      {(() => {
        const currentConnections = img.loreNoteIds || (img.loreNoteId ? [img.loreNoteId] : []);
        if (currentConnections.length > 0) {
          return (
            <div className="mb-2">
              <div className="text-xs text-gray-400 mb-1">Connected to:</div>
              <div className="flex flex-wrap gap-1 justify-center">
                {currentConnections.map(noteId => {
                  const note = loreNotes.find(n => n.id.toString() === noteId.toString());
                  return note ? (
                    <span 
                      key={noteId}
                      className="inline-flex items-center gap-1 px-2 py-1 bg-gray-700 rounded-full text-xs"
                      style={{ color: note.color }}
                    >
                      {note.title}
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          handleUnlinkFromNote(img.id, noteId);
                        }}
                        className="text-red-400 hover:text-red-300 ml-1"
                      >
                        ×
                      </button>
                    </span>
                  ) : null;
                })}
              </div>
            </div>
          );
        }
        return null;
      })()}
    </div>
    
    {/* Multi-select dropdown for LoreNotes */}
    <div className="relative">
      <select
        multiple
        size="4"
        value={img.loreNoteIds || (img.loreNoteId ? [img.loreNoteId] : [])}
        onChange={(e) => {
          const selectedOptions = Array.from(e.target.selectedOptions, option => option.value);
          console.log('Multi-select changed:', { imageId: img.id, selected: selectedOptions });
          handleUpdateImageConnections(img.id, selectedOptions);
        }}
        onClick={(e) => e.stopPropagation()}
        className="w-full text-xs px-3 py-2 rounded-lg bg-gray-700 text-white border border-gray-500 cursor-pointer focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
        style={{ 
          backgroundColor: '#374151',
          color: '#ffffff',
          maxHeight: '120px'
        }}
      >
        {loreNotes.length > 0 ? loreNotes.map(note => (
          <option 
            key={`loreNote-${note.id}`} 
            value={note.id.toString()}
            style={{ 
              backgroundColor: '#1f2937', 
              color: note.color || '#ffffff',
              padding: '4px 8px'
            }}
          >
            📝 {note.title} ({note.category})
          </option>
        )) : (
          <option disabled style={{ backgroundColor: '#1f2937', color: '#9ca3af' }}>
            No LoreNotes available
          </option>
        )}
      </select>
      
      {/* Helper text */}
      <div className="text-xs text-gray-400 mt-1 text-center">
        Hold Ctrl/Cmd to select multiple notes
      </div>
    </div>
    
    {/* Quick action buttons */}
    <div className="flex gap-2 mt-3">
      <button
        onClick={(e) => {
          e.stopPropagation();
          handleClearAllConnections(img.id);
        }}
        className="flex-1 px-2 py-1 bg-red-600 hover:bg-red-700 text-white text-xs rounded transition-colors"
      >
        Clear All
      </button>
      <button
        onClick={(e) => {
          e.stopPropagation();
          handleConnectToAll(img.id);
        }}
        className="flex-1 px-2 py-1 bg-green-600 hover:bg-green-700 text-white text-xs rounded transition-colors"
      >
        Connect All
      </button>
    </div>
  </div>
)}

// Add these new handler functions to your ConceptBoard component:

const handleUpdateImageConnections = async (imageId, selectedNoteIds) => {
  try {
    console.log('Updating image connections:', { imageId, selectedNoteIds });
    
    // Convert string IDs to numbers for server
    const noteIds = selectedNoteIds.map(id => parseInt(id)).filter(id => !isNaN(id));
    
    // For backward compatibility, also set single loreNoteId
    const primaryNoteId = noteIds.length > 0 ? noteIds[0] : null;
    
    const updatePayload = {
      loreNoteIds: noteIds, // Array of connected note IDs
      loreNoteId: primaryNoteId // Primary connection for backward compatibility
    };
    
    console.log('Update payload:', updatePayload);
    
    // Send to server
    const response = await fetch(`http://localhost:5000/api/images/${imageId}`, {
      method: 'PUT',
      headers: { 
        'Content-Type': 'application/json',
        'Accept': 'application/json'
      },
      body: JSON.stringify(updatePayload)
    });

    if (!response.ok) {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }

    const responseData = await response.json();
    console.log('Server response:', responseData);

    // Update local state
    setImages(prev => {
      const updatedImages = prev.map(img => {
        if (img.id === imageId) {
          return { 
            ...img, 
            loreNoteIds: noteIds.map(id => id.toString()),
            loreNoteId: primaryNoteId ? primaryNoteId.toString() : null,
            // Update category based on primary connection
            category: primaryNoteId ? 
              (loreNotes.find(note => note.id === primaryNoteId)?.category || img.category) : 
              img.category
          };
        }
        return img;
      });
      
      localStorage.setItem('conceptBoard_images', JSON.stringify(updatedImages));
      return updatedImages;
    });
    
    console.log('Image connections updated successfully');
    
  } catch (error) {
    console.error('Failed to update image connections:', error);
    
    // Fallback: Update locally even if server fails
    setImages(prev => {
      const updatedImages = prev.map(img => {
        if (img.id === imageId) {
          const noteIds = selectedNoteIds.map(id => parseInt(id)).filter(id => !isNaN(id));
          const primaryNoteId = noteIds.length > 0 ? noteIds[0] : null;
          
          return { 
            ...img, 
            loreNoteIds: noteIds.map(id => id.toString()),
            loreNoteId: primaryNoteId ? primaryNoteId.toString() : null,
            category: primaryNoteId ? 
              (loreNotes.find(note => note.id === primaryNoteId)?.category || img.category) : 
              img.category
          };
        }
        return img;
      });
      
      localStorage.setItem('conceptBoard_images', JSON.stringify(updatedImages));
      return updatedImages;
    });
    
    setErrorMessage("Connection saved locally (server sync will happen when available)");
    setTimeout(() => setErrorMessage(null), 3000);
  }
};

const handleUnlinkFromNote = async (imageId, noteIdToRemove) => {
  const img = images.find(i => i.id === imageId);
  if (!img) return;
  
  const currentConnections = img.loreNoteIds || (img.loreNoteId ? [img.loreNoteId] : []);
  const updatedConnections = currentConnections.filter(id => id.toString() !== noteIdToRemove.toString());
  
  console.log('Unlinking note:', { imageId, noteIdToRemove, currentConnections, updatedConnections });
  
  await handleUpdateImageConnections(imageId, updatedConnections);
};

const handleClearAllConnections = async (imageId) => {
  console.log('Clearing all connections for image:', imageId);
  await handleUpdateImageConnections(imageId, []);
};

const handleConnectToAll = async (imageId) => {
  const allNoteIds = loreNotes.map(note => note.id.toString());
  console.log('Connecting to all notes:', { imageId, allNoteIds });
  await handleUpdateImageConnections(imageId, allNoteIds);
};

// Update the getEffectiveImageCategory function to handle multiple connections:
const getEffectiveImageCategory = (image) => {
  // Check for multiple connections first
  if (image.loreNoteIds && image.loreNoteIds.length > 0 && loreNotes.length > 0) {
    const primaryNote = loreNotes.find(note => note.id.toString() === image.loreNoteIds[0]);
    return primaryNote ? primaryNote.category : image.category;
  }
  
  // Fallback to single connection
  if (image.loreNoteId && loreNotes.length > 0) {
    const linkedNote = loreNotes.find(note => note.id.toString() === image.loreNoteId);
    return linkedNote ? linkedNote.category : image.category;
  }
  
  return image.category;
};

// Update the load data function to handle multiple connections:
const formattedImages = fetchedImages.map(img => ({
  id: img.id.toString(),
  src: `http://localhost:5000${img.url}`,
  x: img.posX || 100,
  y: img.posY || 100,
  name: img.name || img.originalName || 'Untitled',
  loreNoteId: img.loreNoteId ? img.loreNoteId.toString() : null,
  loreNoteIds: img.loreNoteIds ? img.loreNoteIds.map(id => id.toString()) : 
               (img.loreNoteId ? [img.loreNoteId.toString()] : []),
  category: img.category || 'General',
  width: img.width || 300,
  height: img.height || 150
}));
